<template>
  <div class="container settings">
    <q-tab-panels v-model="tab" animated class="page-background">
      <q-tab-panel name="fields">
        <div class="row mt-5">
          <div style="width: 100%">
            <f-btn
              :label="$t('create_field')"
              class="q-ml-md right"
              @click="
                () => {
                  showFieldDetailsForm = true;
                }
              "
            />
            <f-btn
              :label="$t('save_settings')"
              class="right q-ml-md"
              @click="save()"
            />
            <f-btn
              :label="$t('restore_default')"
              class="q-ml-md right"
              @click="restoreDefaultField()"
            />
            <q-input
              class="width-500"
              dense
              v-model="searchInput"
              autofocus
              :placeholder="$t('search')"
              outlined
            />
          </div>
        </div>
        <div class="q-mt-md">
          <div class="full-width">
            <q-markup-table
              dense
              flat
              class="dashboard-table-style fields-table-height back-white dashboard-table-header-sticky"
            >
              <thead>
                <tr class="highlighted-back">
                  <th class="text-h4 text-uppercase">
                    {{ $t('fields') }}
                  </th>
                  <th class="text-h4 text-uppercase">
                    {{ $t('erp_field_name') }}
                  </th>
                  <th class="text-h4 text-uppercase text-center">
                    {{ $t('list_of_values') }}
                  </th>
                  <th class="text-h4 text-uppercase text-center">
                    {{ $t('requierd') }}
                  </th>
                  <th class="text-h4 text-uppercase text-center">
                    {{ $t('read_only') }}
                  </th>
                  <th class="text-h4 text-uppercase text-center">
                    {{ $t('hidden') }}
                  </th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                <template v-for="row in filteredColumns" :key="row.field_name">
                  <tr class="row-header">
                    <td class="text-h4">
                      <q-input
                        dense
                        filled
                        style="background: transparent"
                        v-model="row.title"
                        :label="row.field_name"
                      />
                    </td>
                    <td class="text-h4">
                      <q-input
                        dense
                        filled
                        style="background: transparent"
                        v-model="row.erp_field_name"
                      />
                    </td>
                    <td class="text-h4">
                      <q-select
                        class="option-list"
                        v-if="
                          row.field_type == SELECT ||
                          row.field_type == SEARCH ||
                          row.field_type == RADIO
                        "
                        dense
                        filled
                        v-model="row.list_of_values"
                        style="background: transparent"
                        :rules="[(val: any) => val !== null]"
                        :readonly="row.field_org_id == DEFAULT_ORG_UUID"
                        :options="listOfValues"
                        emit-value
                        map-options
                        :label="$t('list_of_values')"
                      />
                    </td>
                    <td class="text-h4 text-center">
                      <q-checkbox v-model="row.is_required" />
                    </td>
                    <td class="text-h4 text-center">
                      <q-checkbox v-model="row.is_readonly" />
                    </td>

                    <td class="text-h4 text-center">
                      <q-checkbox v-model="row.is_hidden" />
                    </td>

                    <td class="text-h4">
                      <q-btn
                        round
                        size="sm"
                        :color="row.calculation_formula ? 'primary' : 'grey'"
                        icon="add"
                        @click="openCalcDialog(row)"
                      >
                        <q-tooltip>{{ $t('show_metadata') }}</q-tooltip>
                      </q-btn>
                      <q-btn
                        v-if="row.field_org_id === DEFAULT_ORG_UUID"
                        flat
                        color="black"
                        class="pl-6 pr-6"
                        style="cursor: default"
                      >
                        <Icon icon="mdi:delete-off" width="20" height="20" />
                        <q-tooltip>{{ $t('not_trash') }}</q-tooltip>
                      </q-btn>
                      <q-btn
                        v-else
                        flat
                        color="primary"
                        class="pl-6 pr-6"
                        @click="deleteField(row)"
                      >
                        <q-icon name="delete" size="20px" />
                      </q-btn>

                      <q-icon name="info" size="sm">
                        <q-tooltip>
                          <div>{{ $t('name') }} : {{ row.field_name }}</div>
                          <div>{{ $t('type') }} : {{ row.field_type }}</div>
                          <div v-if="row.input_type">
                            {{ $t('document_type') }} : {{ row.input_type }}
                          </div>
                        </q-tooltip>
                      </q-icon>
                    </td>
                  </tr>
                </template>
              </tbody>
            </q-markup-table>
          </div>
        </div>
      </q-tab-panel>
    </q-tab-panels>
  </div>
  <!-- Create New Field dialog -->
  <q-dialog
    v-model="showFieldDetailsForm"
    persistent
    transition-show="scale"
    transition-hide="scale"
    @keydown.esc="showFieldDetailsForm = false"
  >
    <q-card style="width: 50%">
      <q-toolbar class="secondary-toolbar text-white">
        <q-toolbar-title>
          <span class="text-weight-bold">{{ $t('field_details') }}</span>
        </q-toolbar-title>

        <q-btn
          flat
          round
          dense
          v-close-popup
          icon="close"
          @click="closeFieldDlg()"
        />
      </q-toolbar>
      <q-card-section class="row items-center q-pb-none"> </q-card-section>

      <q-card-section>
        <div class="col-sm-12 col-md-12 col-lg-12">
          <q-input
            outlined
            v-model="fieldName"
            required
            :label="$t('name')"
            :rules="[(val: any) => val && val.length > 0]"
          />
        </div>

        <div class="col-sm-12 col-md-12 col-lg-12">
          <q-input
            outlined
            required
            v-model="fieldTitle"
            :rules="[(val: any) => val && val.length > 0]"
            :label="$t('title')"
          />
        </div>

        <div class="col-sm-12 col-md-12 col-lg-12">
          <q-select
            outlined
            required
            v-model="fieldType"
            :rules="[(val: any) => val !== null]"
            :options="field_type_option"
            emit-value
            map-options
            :label="$t('select_field_type')"
          >
            <template v-slot:option="scope">
              <q-item v-bind="scope.itemProps">
                <q-item-section>
                  <q-item-label>{{ $t(scope.opt.label) }}</q-item-label>
                </q-item-section>
              </q-item>
            </template>
          </q-select>
        </div>
        <div class="col-sm-12 col-md-12 col-lg-12">
          <q-select
            v-if="
              fieldType == SELECT || fieldType == SEARCH || fieldType == RADIO
            "
            outlined
            required
            v-model="fieldListOfValue"
            :rules="[(val: any) => val !== null]"
            :options="listOfValues"
            emit-value
            map-options
            :label="'List of value'"
          />
        </div>
        <div v-if="fieldType != FILE" class="col-sm-12 col-md-12 col-lg-12">
          <q-input
            outlined
            required
            v-model="ERPFieldName"
            :rules="[(val: any) => val && val.length > 0]"
            :label="$t('erp_field_name')"
          />
        </div>
        <div class="col-sm-12 col-md-12 col-lg-12">
          <q-input
            v-if="fieldType == FILE"
            outlined
            required
            v-model="documentType"
            :rules="[(val: any) => val && val.length > 0]"
            :label="$t('document_type')"
          />
        </div>
        <div class="col-sm-12 col-md-12 col-lg-12 text-align-center">
          <q-btn
            color="primary"
            :label="$t('back')"
            data-cy="back"
            class="q-mr-sm"
            @click="closeFieldDlg()"
          />
          <q-btn
            color="primary"
            type="submit"
            @click="createFieldInGroup()"
            :label="$t('save')"
            data-cy="save"
          />
        </div>
      </q-card-section>
    </q-card>
  </q-dialog>
  <q-dialog v-model="showFormulaDlg">
    <q-card>
      <q-toolbar class="secondary-toolbar">
        <q-toolbar-title></q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section class="width-500">
        <div class="row">
          <div class="col-sm-12 col-md-12 col-lg-12">
            <div class="row">
              <q-form class="full-width">
                <div class="col-sm-12 col-md-12 col-lg-12">
                  {{ $t('metadata') }}
                </div>

                <div class="col-sm-12 col-md-12 col-lg-12">
                  <q-input
                    outlined
                    v-model="field_model['calculation_formula']"
                    type="textarea"
                  />
                </div>
                <div
                  class="col-sm-12 col-md-12 col-lg-12 text-red-5 height-20 q-pl-md"
                ></div>
                <div class="col-sm-12 col-md-12 col-lg-12">
                  <div class="row q-pt-md">
                    <div class="col-sm-12 col-md-12 col-lg-12 q-pl-md q-pr-md">
                      <q-btn
                        :label="$t('save')"
                        @click="submitFormular()"
                        color="primary"
                        class="full-width"
                        icon="done"
                      />
                    </div>
                  </div>
                </div>
              </q-form>
            </div>
          </div>
        </div>
      </q-card-section>
    </q-card>
  </q-dialog>
  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { defineComponent, ref } from 'vue';
import { useSupplierLayoutsStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import helperMixin from 'src/mixins/helperMixin';
import type { dynamicObj } from 'src/pages/assets';
import { formLayoutInputTypes } from './formBuilderConstants';
import { docFieldsApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions';
import Loader from 'src/components/Loader.vue';
import helperUtil from 'src/utils/helperUtil';
import { listOfValuesApiService } from 'src/services';
import { DEFAULT_ORG_UUID } from 'src/constants';
export default defineComponent({
    el: '#app',
    mixins: [helperMixin, helperUtil],
    components: {
        
        Loader,
    },
    mounted() {
        this.init();
    },
    computed: {
        filteredColumns(): any {
            if (this.searchInput === '') {
                let options = this.field_setting[0]?.rows.flat();
                return options
            }
            
            const needle = this.searchInput.toLowerCase();
            let options = this.field_setting[0].rows.map((row: any) => {
             
            return row.filter((item: any) => {
                const titleMatch = item.title && typeof item.title === 'string' && item.title.toLowerCase().includes(needle);
                const erpMatch = item.erp_field_name && typeof item.erp_field_name === 'string' && item.erp_field_name.toLowerCase().includes(needle);
                 
                return titleMatch || erpMatch;
            });
            }).flat();
            return options;
        }
    },
  data() {
    return {
      searchInput: '',
      tab: ref('fields'),
      showFieldDetailsForm: ref(false),
      fieldName: ref(''),
      fieldTitle: ref(''),
      fieldType: ref(''),
      documentType: ref(''),
      fieldListOfValue: ref(''),
      listOfValues: ref([]),
      ERPFieldName: ref(''),
      checkedFields: ref(false),
      SELECT: formLayoutInputTypes.SELECT,
      SEARCH: formLayoutInputTypes.SEARCH,
      RADIO: formLayoutInputTypes.RADIO,
      FILE: formLayoutInputTypes.FILE,
      field_setting: ref([] as dynamicObj[]),
      showFormulaDlg: ref(false),
      field_type_option: [
        {
          value: formLayoutInputTypes.STRING,
          label: this.$t('string'),
        },
        {
          value: formLayoutInputTypes.TEXTAREA,
          label: this.$t('textarea'),
        },
        {
          value: formLayoutInputTypes.NUMBER,
          label: this.$t('number'),
        },
        {
          value: formLayoutInputTypes.SELECT,
          label: this.$t('select'),
        },
        {
          value: formLayoutInputTypes.SEARCH,
          label: this.$t('select_with_search'),
        },
        {
          value: formLayoutInputTypes.FILE,
          label: this.$t('file'),
        },
        {
          value: formLayoutInputTypes.BOOLEAN,
          label: this.$t('boolean'),
        },
        {
          value: formLayoutInputTypes.RADIO,
          label: this.$t('radio'),
        },
      ] as dynamicObj[],
    };
  },
  setup() {
    const supplier_layouts_store = useSupplierLayoutsStore();
    const { loading } = storeToRefs(supplier_layouts_store);
    let field_model = {} as { [k: string]: any };
    return {
      loading,
      field_model: ref(field_model),
      DEFAULT_ORG_UUID,
    };
  },
  methods: {
    async init() {
      this.showLoading();
      try {
        await this.getDefaultFields();
        await this.fetchListOfValues();
      } catch (error) {
        logError(error);
      } finally {
        this.hideLoading();
      }
    },
    async fetchListOfValues() {
      try {
        const response = await listOfValuesApiService.getLists();
        if (response.success) {
          const listOfValuesOptions = response.data.map(
            (valueList: dynamicObj) => {
              return {
                value: valueList.value,
                label: valueList.label ? valueList.label : valueList.value[0].translated_value, //Need to get translated value else it will show [object object]
              };
            },
          );
          this.listOfValues = listOfValuesOptions;
        }
      } catch (error) {
        logError(error);
      }
    },
    openCalcDialog(row: any) {
      this.field_model = row as dynamicObj;
      this.showFormulaDlg = true;
    },
    submitFormular() {
      this.save();
      this.showFormulaDlg = false;
    },
    async getDefaultFields() {
      try {
        const data = {
          doc_type: 'SUPPLIER_M3',
        };
        const response = await docFieldsApiService.getFieldSettingsByType(data);
        this.field_setting = response.field_setting;
        Array.from(this.field_setting).forEach((group: any) => {
          Array.from(group.rows).forEach((rows: any) => {
            Array.from(rows).forEach((row: any) => {
              if (row.is_required == null) row.is_required = false;
              if (row.is_readonly == null) row.is_readonly = false;
              if (row.is_hidden == null) row.is_hidden = false;
              if (row.force_validation == null) row.force_validation = false;
              if (row.confidence_threshold == null) row.confidence_threshold = 50;
              if (row.match_score_threshold == null) row.match_score_threshold = 50;
            });
          });
        });
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    async save() {
      this.showLoading();
      try {
        const data = { data: JSON.stringify(this.field_setting) };
        await docFieldsApiService.update(data, {
          doc_type: 'SUPPLIER_M3',
          is_sub_doc_type: false,
        });
        await this.getDefaultFields();
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    closeFieldDlg() {
      this.fieldName = '';
      this.fieldTitle = '';
      this.fieldType = '';
      this.ERPFieldName = '';
      this.fieldListOfValue = '';
      this.documentType = '';
      this.showFieldDetailsForm = false;
    },
    validateFieldCreate() {
      let is_valid = true;
      if (this.fieldName === '' || this.fieldName === null) {
        is_valid = false;
        notify.error(this.$t('NAME_MANDATORY'));
      } else if (this.fieldTitle === '' || this.fieldTitle === null) {
        is_valid = false;
        notify.error(this.$t('TITLE_MANDATORY'));
      } else if (this.fieldType === '' || this.fieldType === null) {
        is_valid = false;
        notify.error(this.$t('FIELD_TYPE_MANDATORY'));
      } else if (this.hasWhiteSpace(this.fieldName)) {
        is_valid = false;
        notify.error(this.$t('SPACES_NOT_ALLOWED'));
      } else if (this.checkFirstLetterIsSpecialOrNumber(this.fieldName)) {
        is_valid = false;
        notify.error(
          this.$t('errors_special_letter_number_not_allowed'),
        );
      } else if (
        this.fieldType === this.FILE &&
        (this.documentType === '' || this.documentType === null)
      ) {
        is_valid = false;
        notify.error(this.$t('DOCUMENT_TYPE_MANDATORY'));
      } else if (
        this.fieldType === this.FILE &&
        this.hasWhiteSpace(this.documentType)
      ) {
        is_valid = false;
        notify.error(
          this.$t('SPACES_NOT_ALLOWED_IN_DOCUMENT_TYPE'),
        );
      }

      return is_valid;
    },
    async createFieldInGroup() {
      if (!this.validateFieldCreate()) {
        return;
      }
      this.showLoading();
      try {
        const data: dynamicObj = {
          title: this.fieldTitle,
          field_name: this.fieldName,
          field_type: this.fieldType,
          doc_type_name: 'SUPPLIER_M3',
          group_name: 'SUPPLIER_M3',
        };
        if (
          this.fieldType === this.SELECT ||
          this.fieldType === this.SEARCH ||
          this.fieldType === this.RADIO
        ) {
          data['list_of_values'] = this.fieldListOfValue;
        }
        if (this.fieldType === this.FILE) {
          data['input_type'] = this.documentType;
        } else {
          data['erp_field_name'] = this.ERPFieldName;
        }
        const response = await docFieldsApiService.createField(data);
        if (response.success === false) {
          throw { message: response.message };
        }
        await this.getDefaultFields();
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
      } finally {
        this.closeFieldDlg();
        this.hideLoading();
      }
    },
    async restoreDefaultField() {
      this.showLoading();
      const data = {
        profile: 'DEFAULT',
      };
      try {
        const response = await docFieldsApiService.restoreSupplierField(data);
        if (response.success === false) {
          const msg = ApiExceptions.getErrorMessage(response as dynamicObj);
          notify.error(msg);
          return;
        }
        this.getDefaultFields();
        notify.success(response.message);
      } catch (error) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
      } finally {
        this.hideLoading();
      }
    },
    async deleteField(row: any) {
      this.showLoading();
      try {
        const response = await docFieldsApiService.deleteField(row['id']);
        if (response.success === false) {
          throw { message: response.message };
        }
        this.getDefaultFields();
        notify.success(this.$t('DELETED_SUCCESSFULLY'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },
});
</script>
