.fields-table-height {
  height: calc(100vh - 250px);
  .q-table__top,
  .q-table__bottom,
  thead tr:first-child th {
    /* bg color is important for th; just specify one */
    z-index: 1000; // this will help to fix the problem
  }
  thead tr:first-child th {
    position: sticky;
    top: 0;
  }
}
.option-list {
  padding: 0px;
}
</style>
